            // Now call create – should succeed in mutant because caller is still programOperator
            bytes memory encodedParams = abi.encode(uint256(1), "test");
            address ownedBy = address(0x1111);
            try c.create(encodedParams, ownedBy) {
                // create succeeded – this is what should happen for buggy version after zero-owner
